+ */
+public interface KmpMatchView extends Iterable<Integer> {
+    KmpPattern pattern();
+
+    String text();
+
+    List<Integer> matchIndices();
+
+    default List<Integer> findMatches() {
+        return matchIndices();
+    }
+
